// Merged-texture atlas helper.
//
// `js/atlas.js` (generated by tools/build_atlas.py) exposes COIL_ATLAS with the
// single merged image URL plus the tile index for every coil id and the special
// part keys (__connector, __casing, __glass, __bearing, __reserved).
(function (root) {
  'use strict';

  var atlas = root.COIL_ATLAS || null;
  var img = null;
  var ready = false;
  var waiting = [];

  function has(key) {
    return !!(atlas && atlas.index && atlas.index[key] != null);
  }

  function tile(key) {
    var i = atlas.index[key];
    return [i % atlas.cols, Math.floor(i / atlas.cols)];
  }

  // Inline CSS for a swatch rendered at `px` pixels (nearest-neighbour).
  function style(key, px) {
    if (!has(key)) return null;
    var t = tile(key);
    return {
      backgroundImage: 'url("' + atlas.url + '")',
      backgroundSize: (atlas.cols * px) + 'px ' + (atlas.rows * px) + 'px',
      backgroundPosition: (-t[0] * px) + 'px ' + (-t[1] * px) + 'px',
      backgroundRepeat: 'no-repeat',
      imageRendering: 'pixelated'
    };
  }

  // Inline style string for use inside innerHTML (the enclosing attribute uses
  // double quotes, so the url must use single quotes).
  function cssText(key, px) {
    var s = style(key, px);
    if (!s) return '';
    return "background-image:url('" + atlas.url + "');" +
      'background-size:' + s.backgroundSize + ';' +
      'background-position:' + s.backgroundPosition + ';' +
      'background-repeat:no-repeat;image-rendering:pixelated;';
  }

  function apply(el, key, px) {
    var s = style(key, px);
    if (!s) return false;
    for (var k in s) el.style[k] = s[k];
    return true;
  }

  // Lazily load the atlas image; `cb` runs once it is available.
  function load(cb) {
    if (!atlas) { if (cb) cb(false); return null; }
    if (ready) { if (cb) cb(true); return img; }
    if (cb) waiting.push(cb);
    if (!img && typeof Image !== 'undefined') {
      img = new Image();
      img.onload = function () {
        ready = true;
        var q = waiting; waiting = [];
        for (var i = 0; i < q.length; i++) q[i](true);
      };
      img.onerror = function () {
        ready = false;
        var q = waiting; waiting = [];
        for (var i = 0; i < q.length; i++) q[i](false);
      };
      img.src = atlas.url;
    }
    return img;
  }

  var api = { atlas: atlas, has: has, tile: tile, style: style, cssText: cssText,
              apply: apply, load: load, isReady: function () { return ready; },
              image: function () { return img; } };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  root.TurbineTexture = api;
})(typeof window !== 'undefined' ? window : globalThis);
